import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Img } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type DatingProfileProps = Record<string, any>;

const DatingProfile: React.FC<DatingProfileProps> = ({
  backgroundColor = "#f3f4f6",
  transparentBackground = false,
  durationInSeconds = 12,
  cardScale = 1.0,
  secondsPerCard = 2.0,
  showMatchOnLast = true,
  daters = [
    {
      name: "Jordan",
      age: "26",
      bio: "Always planning the next weekend trip. Looking for a travel buddy.",
      image: "https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=800&q=80",
      action: "nope"
    },
    {
      name: "Alex",
      age: "29",
      bio: "Coffee enthusiast. My dog is probably cuter than you.",
      image: "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=800&q=80",
      action: "superlike"
    },
    {
      name: "Sam",
      age: "24",
      bio: "Just looking for someone to share pizza with on a Friday night.",
      image: "https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=800&q=80",
      action: "like"
    }
  ]
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter", "Poppins"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Radar Animation for Background
  const radarCycleLength = fps * 2.5;
  const radarProgress = (frame % radarCycleLength) / radarCycleLength;
  const radarScale = interpolate(radarProgress, [0, 1], [0, 2]);
  const radarOpacity = interpolate(radarProgress, [0, 0.6, 1], [0.8, 0.4, 0], { extrapolateRight: "clamp" });

  const cardDurationFrames = Math.floor(secondsPerCard * fps);
  const swipeDurationFrames = Math.floor(0.7 * fps);

  // Match Screen Logic
  const lastSwipeFinishFrame = daters.length * cardDurationFrames - swipeDurationFrames + 10;
  const matchProgress = spring({
    fps,
    frame: frame - lastSwipeFinishFrame,
    config: { damping: 14, stiffness: 100 }
  });

  const cardHeight = height * 0.75;
  const cardWidth = cardHeight * 0.65;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden" }}>
      
      {/* Radar Background */}
      <div style={{
        position: 'absolute',
        top: '50%', left: '50%',
        width: height, height: height,
        transform: 'translate(-50%, -50%)',
        display: 'flex', justifyContent: 'center', alignItems: 'center',
        zIndex: 0
      }}>
        <div style={{
          position: 'absolute',
          width: '40%', height: '40%',
          borderRadius: '50%',
          backgroundColor: '#e5e7eb',
        }} />
        <div style={{
          position: 'absolute',
          width: '100%', height: '100%',
          borderRadius: '50%',
          border: '2px solid rgba(229, 231, 235, 0.6)',
          transform: `scale(${radarScale})`,
          opacity: radarOpacity,
        }} />
      </div>

      {/* Cards Container */}
      <div style={{
        position: "absolute",
        width, height,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        transform: `scale(${cardScale})`,
        zIndex: 10
      }}>
        {[...daters].reverse().map((dater, reversedIndex) => {
          const i = daters.length - 1 - reversedIndex;

          const outTime = (i + 1) * cardDurationFrames - swipeDurationFrames;
          const inTime = i * cardDurationFrames - swipeDurationFrames;

          const outProgress = spring({
            fps,
            frame: frame - outTime,
            config: { damping: 14, stiffness: 90 }
          });

          const inProgress = i === 0 ? 1 : spring({
            fps,
            frame: frame - inTime,
            config: { damping: 14, stiffness: 90 }
          });

          const scale = interpolate(inProgress, [0, 1], [0.9, 1]);
          const cardOpacity = interpolate(inProgress, [0, 0.5], [0, 1]);

          const translateX = interpolate(outProgress, [0, 1], [
            0,
            dater.action === "nope" ? -width * 1.5 : dater.action === "like" ? width * 1.5 : 0
          ]);

          const translateY = interpolate(outProgress, [0, 1], [
            0,
            dater.action === "superlike" ? -height * 1.5 : 0
          ]);

          const rotate = interpolate(outProgress, [0, 1], [
            0,
            dater.action === "nope" ? -25 : dater.action === "like" ? 25 : 0
          ]);

          const stampOpacity = interpolate(outProgress, [0, 0.15], [0, 1], { extrapolateRight: "clamp" });

          return (
            <div
              key={`card-${i}`}
              style={{
                position: "absolute",
                width: cardWidth,
                height: cardHeight,
                backgroundColor: "#fff",
                borderRadius: 24,
                overflow: "hidden",
                border: "1px solid rgba(0,0,0,0.1)", // Replaced heavy boxShadow with lightweight border
                transform: `translateX(${translateX}px) translateY(${translateY}px) rotate(${rotate}deg) scale(${scale})`,
                opacity: cardOpacity,
                transition: "none",
                willChange: "transform"
              }}
            >
              <Img 
                src={dater.image} 
                style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} 
              />
              
              <div style={{
                position: "absolute",
                bottom: 0,
                left: 0,
                right: 0,
                height: "45%",
                background: "linear-gradient(to top, rgba(0,0,0,0.9) 0%, rgba(0,0,0,0.6) 40%, rgba(0,0,0,0) 100%)",
                display: "flex",
                flexDirection: "column",
                justifyContent: "flex-end",
                padding: "32px 24px",
                transition: "none"
              }}>
                <div style={{ display: "flex", alignItems: "baseline", gap: 12 }}>
                  <span style={{ fontSize: 42, fontWeight: 700, color: "white" }}>{dater.name}</span>
                  <span style={{ fontSize: 32, fontWeight: 400, color: "white" }}>{dater.age}</span>
                </div>
                <p style={{ fontSize: 20, color: "rgba(255,255,255,0.9)", marginTop: 8, lineHeight: 1.4, margin: "8px 0 0 0" }}>
                  {dater.bio}
                </p>
              </div>

              {/* Action Stamps */}
              {dater.action === "nope" && (
                <div style={{
                  position: "absolute",
                  top: 50,
                  right: 40,
                  border: "8px solid #ff695b",
                  borderRadius: 12,
                  padding: "4px 16px",
                  transform: "rotate(15deg)",
                  opacity: stampOpacity,
                  transition: "none"
                }}>
                  <span style={{ fontSize: 54, fontWeight: 900, color: "#ff695b", letterSpacing: 2 }}>NOPE</span>
                </div>
              )}
              {dater.action === "like" && (
                <div style={{
                  position: "absolute",
                  top: 50,
                  left: 40,
                  border: "8px solid #43e59c",
                  borderRadius: 12,
                  padding: "4px 16px",
                  transform: "rotate(-15deg)",
                  opacity: stampOpacity,
                  transition: "none"
                }}>
                  <span style={{ fontSize: 54, fontWeight: 900, color: "#43e59c", letterSpacing: 2 }}>LIKE</span>
                </div>
              )}
              {dater.action === "superlike" && (
                <div style={{
                  position: "absolute",
                  bottom: "35%",
                  left: "50%",
                  border: "8px solid #3ca4ff",
                  borderRadius: 12,
                  padding: "4px 16px",
                  transform: "translateX(-50%) rotate(-10deg)",
                  opacity: stampOpacity,
                  transition: "none"
                }}>
                  <span style={{ fontSize: 54, fontWeight: 900, color: "#3ca4ff", letterSpacing: 2 }}>SUPER LIKE</span>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Match Screen Overlay */}
      {showMatchOnLast && frame >= lastSwipeFinishFrame && (
        <AbsoluteFill style={{
          backgroundColor: `rgba(0,0,0,${interpolate(matchProgress, [0, 1], [0, 0.95])})`, // Increased opacity slightly to compensate for removed blur
          // Removed extremely expensive backdropFilter: blur() to fix performance issues
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          flexDirection: "column",
          zIndex: 20,
          transition: "none"
        }}>
          <div style={{
            transform: `scale(${interpolate(matchProgress, [0, 1], [0.5, 1])})`,
            opacity: interpolate(matchProgress, [0, 1], [0, 1]),
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            transition: "none"
          }}>
            <h1 style={{
              fontFamily: "Poppins",
              fontSize: 100,
              fontWeight: 900,
              color: "#fff",
              // Removed heavy textShadow for rendering performance
              margin: 0,
              fontStyle: "italic",
              letterSpacing: 4
            }}>
              IT'S A MATCH!
            </h1>
            <p style={{
              fontFamily: "Inter",
              fontSize: 28,
              color: "rgba(255,255,255,0.8)",
              marginTop: 16
            }}>
              You and {daters[daters.length - 1].name} liked each other.
            </p>
            
            <div style={{
              marginTop: 60,
              width: 200,
              height: 200,
              borderRadius: "50%",
              overflow: "hidden",
              border: "6px solid #43e59c",
              // Removed heavy boxShadow for rendering performance
            }}>
              <Img 
                src={daters[daters.length - 1].image} 
                style={{ width: "100%", height: "100%", objectFit: "cover" }} 
              />
            </div>
          </div>
        </AbsoluteFill>
      )}

    </AbsoluteFill>
  );
};

export default DatingProfile;